    }
    ptc_carrying->RemoveThingFromPrimarySlot(false);
    if (IS_THING_ALIVE(PPreviouslyCarriedItem) && PPreviouslyCarriedItem->HasTC(TCI_WEAPON))
        PPreviouslyCarriedItem->Kill(true);
